import numpy as np
A=np.array(g)
def comps(A,diag=False):
 h,w=A.shape; seen=set(); out=[]
 for r,c in zip(*np.where(A!=0)):
  if (r,c) in seen:continue
  stack=[(r,c)];seen.add((r,c));cc=[]
  while stack:
   x,y=stack.pop();cc.append((x,y))
   for dx in [-1,0,1]:
    for dy in [-1,0,1]:
     if (dx==0 and dy==0) or (not diag and abs(dx)+abs(dy)!=1):continue
     nx,ny=x+dx,y+dy
     if 0<=nx<h and 0<=ny<w and A[nx,ny]!=0 and (nx,ny) not in seen:seen.add((nx,ny));stack.append((nx,ny))
  out.append(cc)
 return out
for diag in [False,True]:
 cs=comps(A,diag)
 print(diag,len(cs),[(len(c),(min(x for x,y in c),min(y for x,y in c),max(x for x,y in c),max(y for x,y in c))) for c in sorted(cs,key=len,reverse=True)])
